def match(orders):
    trades = []
    # book[side] = {price: [(order_id, remaining_qty, arrival_time), ...]}
    book = {'buy': {}, 'sell': {}}
    # Track all order states: {order_id: ('limit'|'ioc'|'market', side, price, original_qty, remaining_qty, arrival_time, filled)}
    order_states = {}
    arrival_counter = 0

    for order in orders:
        order_type = order[0]
        arrival_counter += 1

        if order_type == 'cancel':
            order_id = order[1]
            if order_id in order_states:
                state = order_states[order_id]
                if state[6] == False:  # not yet filled/cancelled
                    side = state[1]
                    price = state[2]
                    if price in book[side]:
                        book[side][price] = [(oid, qty, arr) for oid, qty, arr in book[side][price] if oid != order_id]
                        if not book[side][price]:
                            del book[side][price]
                    order_states[order_id] = (state[0], state[1], state[2], state[3], 0, state[5], True)
            continue

        order_id = order[1]
        side = order[2]

        if order_type == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        # Match against resting orders
        remaining_qty = qty
        opposite_side = 'sell' if side == 'buy' else 'buy'

        if side == 'buy':
            # Match against sell orders: lowest price first, then earliest
            sell_prices = sorted(book['sell'].keys())
            for sell_price in sell_prices:
                if price is not None and sell_price > price:
                    break
                while remaining_qty > 0 and book['sell'][sell_price]:
                    resting_id, resting_qty, resting_arrival = book['sell'][sell_price][0]
                    trade_qty = min(remaining_qty, resting_qty)
                    trades.append([order_id, resting_id, sell_price, trade_qty])
                    remaining_qty -= trade_qty
                    resting_qty -= trade_qty

                    if resting_qty == 0:
                        book['sell'][sell_price].pop(0)
                        state = order_states[resting_id]
                        order_states[resting_id] = (state[0], state[1], state[2], state[3], 0, state[5], True)
                    else:
                        book['sell'][sell_price][0] = (resting_id, resting_qty, resting_arrival)
                if not book['sell'][sell_price]:
                    del book['sell'][sell_price]
        else:  # sell
            # Match against buy orders: highest price first, then earliest
            buy_prices = sorted(book['buy'].keys(), reverse=True)
            for buy_price in buy_prices:
                if price is not None and buy_price < price:
                    break
                while remaining_qty > 0 and book['buy'][buy_price]:
                    resting_id, resting_qty, resting_arrival = book['buy'][buy_price][0]
                    trade_qty = min(remaining_qty, resting_qty)
                    trades.append([resting_id, order_id, buy_price, trade_qty])
                    remaining_qty -= trade_qty
                    resting_qty -= trade_qty

                    if resting_qty == 0:
                        book['buy'][buy_price].pop(0)
                        state = order_states[resting_id]
                        order_states[resting_id] = (state[0], state[1], state[2], state[3], 0, state[5], True)
                    else:
                        book['buy'][buy_price][0] = (resting_id, resting_qty, resting_arrival)
                if not book['buy'][buy_price]:
                    del book['buy'][buy_price]

        # Handle post-match resting
        if order_type == 'limit' and remaining_qty > 0:
            if price not in book[side]:
                book[side][price] = []
            book[side][price].append((order_id, remaining_qty, arrival_counter))
            order_states[order_id] = (order_type, side, price, qty, remaining_qty, arrival_counter, False)
        else:
            order_states[order_id] = (order_type, side, price, qty, remaining_qty if order_type == 'limit' else 0, arrival_counter, remaining_qty == 0)

    return trades

